/* Generated by scripts/gen-shard-rename.h — do not edit by hand.
 *
 * When PANDA_LWIP_SHARD_PREFIX is defined, every symbol the lwIP core and
 * its port export is renamed with that prefix via token pasting. Compiling
 * the identical sources once per prefix yields multiple fully independent
 * stack instances (separate globals, pools, pcb lists, timers) linkable
 * into one process. The primary stack compiles WITHOUT the prefix and is
 * byte-for-byte unaffected.
 */
